{"hypotheses": [
  {
    "name": "Contrarian Profitability Across Volatility Regimes",
    "mechanism": "Profitability (OperProf) and long-term reversal (LRreversal) capture distinct market anomalies. Combining them and applying only when implied equity volatility (VIX) is below its trailing median targets environments where behavioral underreaction to fundamentals and mean reversion both prevail, potentially enhancing risk-adjusted returns beyond the individual effects.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 1.0, "primitive": "LRreversal"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "OperProf", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.95,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Intangible Value-Momentum Synergy",
    "mechanism": "Intangible value (IntanBM) and off-season momentum (MomOffSeason) exploit different inefficiencies: mispricing of intangibles and behavioral persistence outside typical momentum windows. Their combination should reduce cyclicality and improve performance—particularly in small caps where such inefficiencies are more pronounced.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IntanBM"},
        {"weight": 0.5, "primitive": "MomOffSeason"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "IntanBM", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.80,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Low Leverage High Organizational Capital",
    "mechanism": "Firms with high organizational capital (OrgCap) and low market leverage (Leverage, negatively weighted) may deliver superior returns due to efficient resource utilization and reduced risk of distress, especially during periods of positive term spread indicating healthy economic conditions.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": -1.0, "primitive": "Leverage"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Analyst Disagreement Defensive Overlay",
    "mechanism": "Combining high forecast dispersion (ForecastDispersion) with defensive profitability (OperProfRD) and applying only when the market has declined over the prior 12 months (MKT_TRAILING_12M_DOWN) creates a composite that should benefit from mispricings exacerbated by uncertainty, while defensive quality limits drawdowns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": 1.0, "primitive": "OperProfRD"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "correlation", "primitive": "ForecastDispersion", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Anti-Equity Issuance Quality Mix",
    "mechanism": "Firms with low net equity financing (NetEquityFinance, negative) and high Piotroski F-score (PS) combine capital discipline with robust fundamentals, potentially yielding excess returns by avoiding dilution and favoring operational strength. This should be especially effective when credit spreads are low (TERM_SPREAD_POSITIVE).",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "NetEquityFinance"},
        {"weight": 1.0, "primitive": "PS"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "NetEquityFinance", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Liquidity Contrarian in Bear Markets",
    "mechanism": "Stocks with wide bid-ask spreads (BidAskSpread, negative) and high short-term reversal (STreversal) are likely to be oversold during down markets. Combining these and activating only after market declines (MKT_TRAILING_12M_DOWN) should capture liquidity-driven mispricings more effectively than either alone.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "BidAskSpread"},
        {"weight": 1.0, "primitive": "STreversal"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "BidAskSpread", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.72,
    "expected_decay_half_life_months": 15
  },
  {
    "name": "Asset Growth and Customer Momentum Divergence",
    "mechanism": "Combining low asset growth (AssetGrowth, negative) with positive customer momentum (CustomerMomentum) yields a portfolio likely to avoid overinvestment traps while capturing supply-chain-driven outperformance—an effect that should be more robust in the US than in emerging markets.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": 1.0, "primitive": "CustomerMomentum"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "international", "region": "emerging", "direction": "opposite_sign"},
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.78,
    "expected_decay_half_life_months": 28
  },
  {
    "name": "Share Repurchase and High Volatility Quality",
    "mechanism": "Firms engaging in share repurchases (ShareRepurchase) and exhibiting high volume variance (VolSD) often signal undervaluation and attract contrarian capital. Activating this combination only in high VIX regimes should amplify the premium by exploiting heightened risk aversion.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShareRepurchase"},
        {"weight": 1.0, "primitive": "VolSD"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.82,
    "expected_decay_half_life_months": 20
  }
]}
